// 合併 GitHub Trending + HN 結果
const githubData = $('GitHub Trending').first().json;
const githubRepos = Array.isArray(githubData) ? githubData : (githubData.repos || []);

const githubNews = githubRepos.slice(0, 10).map(r => ({
  title: r.name || r.full_name,
  summary: r.description || '無描述',
  url: r.html_url || r.url,
  source: 'GitHub',
  score: Math.min(Math.floor((r.stars || 0) / 100), 10),
  tags: [r.language || '開源', '熱門'].filter(Boolean)
}));

const hnData = $('LLM 處理 HN').all().map(d => d.json).filter(j => j && j.title);
const hnNews = hnData.map(j => {
  try {
    const content = typeof j === 'string' ? JSON.parse(j) : j;
    return {
      title: content.title || '無標題',
      summary: content.text ? content.text.substring(0, 200) : (content.summary || '無描述'),
      url: content.url || `https://news.ycombinator.com/item?id=${content.id}`,
      source: 'Hacker News',
      score: content.score ? Math.min(Math.floor(content.score / 10), 10) : 5,
      tags: ['科技', '討論']
    };
  } catch(e) { return null; }
}).filter(Boolean);

return [{json: {news: [...githubNews, ...hnNews]}}];

const newsData = $input.first().json.news;
const keywordCount = {};

newsData.forEach(item => {
  const words = (item.title + ' ' + item.summary).split(/[\s\-,;:，。、]/);
  words.forEach(w => {
    if (w.length > 3 && !['https', 'http', 'github', 'com', 'www', 'org', 'net'].includes(w.toLowerCase())) {
      keywordCount[w] = (keywordCount[w] || 0) + 1;
    }
  });
});

const topKeywords = Object.entries(keywordCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([word, count]) => ({word, count}));

return [{json: {trending: topKeywords, news: newsData}}];
